import{XO_CONFIG as l}from"./config.min.js";export const KINDS=Object.freeze(["fifty","pick","catch","sack","tackle","release"]);export function ballEvent(r,e){return!r||!e||!e.thrown||!e.holder||e.holder===r.holder||r.holder&&r.thrown?null:{kind:e.team===0?"catch":"pick",hero:e.holder,partner:null}}export function tackleKind({carrier:r,threw:e,ran:c}){return r==="qb"&&!e&&!c?"sack":"tackle"}export function delayFor(r){const e=l.moments.after[r];return Number.isFinite(e)&&e>0?e:0}export function involves(r,e){return!!e&&(r.hero===e||r.partner===e)}export function rankMoments(r,e=null,c=l.moments.keep){const a=r.some(t=>t.kind!=="release"),i=r.filter(t=>t.kind!=="release"||!a||involves(t,e)),o=t=>t.kind==="release"?2:involves(t,e)?0:1;return i.map((t,n)=>({m:t,i:n})).sort((t,n)=>o(t.m)-o(n.m)||KINDS.indexOf(t.m.kind)-KINDS.indexOf(n.m.kind)||(t.m.at||0)-(n.m.at||0)||t.i-n.i).slice(0,Math.max(0,c)).map(({m:t})=>t)}export const KIND_NAMES=Object.freeze({fifty:"Fifty",pick:"Interception",catch:"Catch",sack:"Sack",tackle:"Tackle",release:"Throw"});
